<script>
(function(){
  var ids=['c25-bc','c25-imgcol','c25-info'];
  function trigger(){ids.forEach(function(id){var el=document.getElementById(id);if(el)el.classList.add('c25-vis');});}
  if(document.readyState==='complete'){trigger();}else{window.addEventListener('load',trigger);}
  var mainImg=document.getElementById('c25-main-img');
  var thumbs=document.querySelectorAll('.c25-hero__thumb');
  thumbs.forEach(function(thumb){
    thumb.addEventListener('click',function(){
      var src=thumb.getAttribute('data-src');
      if(src&&mainImg){mainImg.style.opacity='0';mainImg.style.transition='opacity .2s ease';setTimeout(function(){mainImg.src=src;mainImg.style.opacity='1';},180);}
      thumbs.forEach(function(t){t.classList.remove('c25-hero__thumb--active');});
      thumb.classList.add('c25-hero__thumb--active');
    });
  });
})();
</script>
