      <div class="mu7-specs__row"><span class="mu7-specs__label">Plattform</span><span class="mu7-specs__val mu7-specs__val--highlight">nano ZST+ (kompakte ZONE Sonography Technology)</span></div>
      <div class="mu7-specs__row"><span class="mu7-specs__label">Gewicht</span><span class="mu7-specs__val mu7-specs__val--highlight">2 kg (ohne Sonden)</span></div>
